def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    best = None

    # Search for the strongest rectangular outline, allowing stray same-color
    # pixels outside it without expanding the outline's bounds.
    for color in counts:
        if color == bg:
            continue
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        perimeter = ([(r0, c) for c in range(c0, c1 + 1)] +
                                     [(r1, c) for c in range(c0, c1 + 1)] +
                                     [(r, c0) for r in range(r0 + 1, r1)] +
                                     [(r, c1) for r in range(r0 + 1, r1)])
                        support = sum(grid[r][c] == color for r, c in perimeter)
                        # Favor a highly supported outline, then its size.
                        score = (support / len(perimeter), support,
                                 (r1-r0+1) * (c1-c0+1))
                        if best is None or score > best[0]:
                            best = (score, color, r0, r1, c0, c1)

    _, color, r0, r1, c0, c1 = best
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r in (r0, r1) or c in (c0, c1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
